// Общие локаторы для тестов legal-docs (#d7fe2c). План: specs/legal-docs.md.
// Expo-роутер держит скрытые экраны в DOM — все локаторы только по видимым элементам.
import * as path from 'path';
import { Page, expect } from '@playwright/test';

export const PARENT_B = path.resolve(__dirname, '../../../auth/parent-b.json');

export const DOCS = {
  terms: { url: '/consent?doc=terms', urlRe: /\/consent\?doc=terms$/, title: 'תנאי השימוש', section: 'מה זה Benjico' },
  privacy: { url: '/consent?doc=privacy', urlRe: /\/consent\?doc=privacy$/, title: 'מדיניות הפרטיות', section: 'אילו נתונים נשמרים' },
} as const;

/** Видимый текст с точным совпадением. */
export const visibleText = (page: Page, text: string | RegExp) =>
  page.getByText(text, { exact: true }).filter({ visible: true }).first();

/** «→ חזרה» экрана документа (не скрытый «→ חזרה להגדרות»). */
export const backButton = (page: Page) => page.locator('text=/^→ חזרה$/ >> visible=true').first();

/** Документ открыт: адрес не сменился (нет редиректа на /children), заголовок и раздел текста видны. */
export async function expectDocOpen(page: Page, doc: keyof typeof DOCS) {
  const d = DOCS[doc];
  await expect(visibleText(page, d.title)).toBeVisible();
  await expect(visibleText(page, d.section)).toBeVisible();
  await expect(page).toHaveURL(d.urlRe);
}
